# 41q_profess_turb_bivariate_robustness.R
#
# PJ, 14 Sep 2026: "maybe I should say the mediation did not work so the
# reported relationship is bivariate with a lag on[e], quadratic - as what
# the chapter concludes on." Sensible simplification - trust never mediates
# anything in any spec (41o/41p/51/51b all agree, ACME always n.s.), so the
# chapter's real headline claim can just be the direct bivariate
# Professionalisation(t-1) -> Turbulence(t), quadratic (41n's existing
# lag-1 result: R²=0.458, quad term p=5.04e-05, GAM edf=2.70 - genuine
# curvature, not a straight line forced through a polynomial).
#
# BUT: 41n has never been trend/first-difference checked - only the full
# mediation model's direct/total effects (51/51b) got that scrutiny. A
# bivariate relationship between two independently-trending series needs
# exactly the same scrutiny before it can be the chapter's headline finding,
# especially since the closely-related mediation-model levels effect
# (same IVs, same quadratic form) was found NOT to survive detrending.
# This script applies the identical two-strategy method (linear+quadratic
# calendar-time control; separately, first-differencing) to THIS specific
# bivariate lag-1 quadratic relationship.
#
# OUTPUT: console only - feeds the footnote/appendix decision.

if (!require("pacman")) install.packages("pacman")
pacman::p_load(dplyr, readr, tibble, sandwich, lmtest, mgcv)

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT <- .ROOT
norm01 <- function(x) (x - min(x, na.rm = TRUE)) / (max(x, na.rm = TRUE) - min(x, na.rm = TRUE))
YEARS  <- 1979:2025

career_obs <- bind_rows(
  tribble(~year,~pct, 1979,3.0, 1983,4.5, 2010,14.0, 2015,17.0, 2019,21.0),
  tribble(~year,~pct, 1987,5.4, 1992,7.3, 1997,9.5, 2001,10.5, 2005,14.1)
) |> arrange(year)
career_annual <- tibble(year = YEARS) |>
  mutate(obs_yr = sapply(year, function(y) max(career_obs$year[career_obs$year <= y])),
         career_pct = career_obs$pct[match(obs_yr, career_obs$year)])
spads <- read_csv(file.path(PROJECT, "data/raw/spads_DATA_ENTRY.csv"), show_col_types = FALSE) |> filter(year <= 2025)
spads_annual <- tibble(year = YEARS, n_spads = approx(spads$year, spads$n_spads, xout = YEARS, rule = 2)$y)
ipsa  <- read_csv(file.path(PROJECT, "data/processed/ipsa_staffing_annual.csv"), show_col_types = FALSE) |>
  select(cal_year, staffing_real = mean_staffing_real_2015)
pre10 <- read_csv(file.path(PROJECT, "data/processed/staffing_pre2010_calibrated_butler.csv"), show_col_types = FALSE) |>
  filter(!is.na(real_2015_mean)) |> select(cal_year = year, staffing_real = real_2015_mean)
staffing_obs <- bind_rows(pre10, ipsa) |> arrange(cal_year) |> filter(cal_year <= 2025)
staffing_annual <- tibble(year = YEARS) |>
  mutate(obs_yr = sapply(year, function(y) max(staffing_obs$cal_year[staffing_obs$cal_year <= y])),
         staffing_real = staffing_obs$staffing_real[match(obs_yr, staffing_obs$cal_year)])
d_prof <- tibble(year = YEARS) |>
  left_join(career_annual  |> select(year, career_pct), by = "year") |>
  left_join(spads_annual   |> select(year, n_spads), by = "year") |>
  left_join(staffing_annual |> select(year, staffing_real), by = "year") |>
  mutate(career_norm = norm01(career_pct), spads_norm = norm01(n_spads), staffing_norm = norm01(staffing_real))
pca_res <- prcomp(d_prof |> select(career_norm, spads_norm, staffing_norm), scale. = TRUE, center = TRUE)
d_prof  <- d_prof |> mutate(prof_pc1 = pca_res$x[, 1])
turb <- read_csv(file.path(PROJECT, "../composite_canonical/canonical_pc1_1979_2025.csv"), show_col_types = FALSE) |>
  select(year, turb_pc1 = PC1_index)

d <- tibble(year = YEARS) |>
  left_join(d_prof |> select(year, prof_pc1), by = "year") |>
  left_join(turb, by = "year") |>
  mutate(prof_lag1 = dplyr::lag(prof_pc1, 1)) |>
  filter(!is.na(prof_lag1), !is.na(turb_pc1)) |>
  arrange(year) |>
  mutate(t = year - mean(year), t2 = t^2)

cat(sprintf("N = %d, years %d-%d\n", nrow(d), min(d$year), max(d$year)))

tidy <- function(mod, term, se="OLS") {
  z <- if (se=="HAC") coeftest(mod, vcov=NeweyWest(mod, lag=1, prewhite=FALSE)) else summary(mod)$coefficients
  sprintf("%s (%s): est=%.3f, p=%.4g", term, se, z[term,1], z[term,4])
}

cat("\n=== BASELINE: turb ~ prof_lag1 + prof_lag1^2 ===\n")
m_base <- lm(turb_pc1 ~ prof_lag1 + I(prof_lag1^2), data = d)
print(summary(m_base)$coefficients)
cat(tidy(m_base, "prof_lag1", "HAC"), " | ", tidy(m_base, "I(prof_lag1^2)", "HAC"), "\n")
g_base <- gam(turb_pc1 ~ s(prof_lag1, k=5), data = d)
cat(sprintf("GAM: edf=%.2f, p=%.4g, dev.expl=%.3f, R2=%.3f\n",
            summary(g_base)$edf, summary(g_base)$s.table[1,"p-value"], summary(g_base)$dev.expl, summary(m_base)$r.squared))

cat("\n=== TREND-ADJUSTED: + linear/quadratic calendar time ===\n")
m_trend <- lm(turb_pc1 ~ prof_lag1 + I(prof_lag1^2) + t + t2, data = d)
print(summary(m_trend)$coefficients)
cat(tidy(m_trend, "prof_lag1", "HAC"), " | ", tidy(m_trend, "I(prof_lag1^2)", "HAC"), "\n")
g_trend <- gam(turb_pc1 ~ s(prof_lag1, k=5) + t + t2, data = d)
cat(sprintf("GAM+trend: s() p=%.4g, dev.expl=%.3f\n", summary(g_trend)$s.table[1,"p-value"], summary(g_trend)$dev.expl))

cat("\n=== FIRST-DIFFERENCED: d_turb ~ d_prof_lag1 (levels) ===\n")
dd <- d |> mutate(d_prof = prof_lag1 - dplyr::lag(prof_lag1), d_turb = turb_pc1 - dplyr::lag(turb_pc1)) |>
  filter(!is.na(d_prof), !is.na(d_turb))
cat(sprintf("N (first-diff) = %d\n", nrow(dd)))
m_diff <- lm(d_turb ~ d_prof + I(d_prof^2), data = dd)
print(summary(m_diff)$coefficients)
cat(tidy(m_diff, "d_prof", "HAC"), " | ", tidy(m_diff, "I(d_prof^2)", "HAC"), "\n")
